                                                                        "event": {
                                                                            "apiName": "sn_uxf.MACROPONENT_STATE_UPDATE_REQUESTED",
                                                                            "payload": {
                                                                                "script": {
                                                                                    "apiVersion": "1.0.0",
                                                                                    "controllerElementId": null,
                                                                                    "inlineScript": "/**\n* @param {params} params\n* @param {api} params.api\n* @param {any} params.event\n*/\nfunction evaluateEvent({api, event}) {\n\tvar prop = {\n\t\tpropName: 'msp_modal_data',\n\t\tvalue: {\n\t\t\tshiftPosition: api.item.value,\n\t\t\tshiftWorkers: []\n\t\t}\n\t};\n\tif (!api.state.auto_save) {\n\t\t// Todo: Enable \"Manage\" action when auto-save off\n\t\treturn prop;\n\t}\n\n\tvar shiftPositionWorkers;\n\tif (api.state.auto_save) {\n\t\tshiftPositionWorkers = api.data.look_up_shift_position_workers.results;\n\t} else {\n\t\tshiftPositionWorkers = api.state.shift_position_workers_replica;\n\t\treturn;\n\t}\n\n\t// When auto-saving, will never loop over unassigned workers\n\tprop.value.shiftWorkers = shiftPositionWorkers.filter(spw => {\n\t\treturn spw.shift_worker._reference.shift._reference.order_in_the_day.value == api.state.selected_shift;\n\t}).map(spw => {\n\t\tvar isWorkerInSelectedPosition = spw.shift_position.value == api.item.value._row_data.uniqueValue;\n\t\treturn {\n\t\t\tid: spw.shift_worker._reference.worker.value,\n\t\t\tlabel: spw.shift_worker._reference.worker.displayValue,\n\t\t\tadult: spw.shift_worker._reference.worker._reference.adult.value,\n\t\t\tactive: isWorkerInSelectedPosition,\n\t\t\tassigned: isWorkerInSelectedPosition,\n\t\t\tshiftWorker: spw.shift_worker.value,\n\t\t\tshiftPositionWorker: spw._row_data.uniqueValue\n\t\t};\n\t});\n\n\t// Add unassigned workers (stored in state as artificial spw's)\n\tapi.state.unassigned_workers.forEach(wkr => {\n\t\tprop.value.shiftWorkers.push({\n\t\t\tid: wkr.shift_worker._reference.worker.value,\n\t\t\tlabel: wkr.shift_worker._reference.worker.displayValue,\n\t\t\tadult: wkr.shift_worker._reference.worker._reference.adult.value,\n\t\t\tactive: true,\n\t\t\tassigned: false,\n\t\t\tshiftWorker: wkr.shift_worker.value\n\t\t});\n\t});\n\treturn prop;\n}",
