                                                                                    "apiVersion": "1.0.0",
                                                                                    "controllerElementId": null,
                                                                                    "inlineScript": "/**\n* @param {params} params\n* @param {api} params.api\n* @param {any} params.event\n* @param {any} params.imports\n*/\nfunction evaluateEvent({api, event, imports}) {\n\tvar params = {};\n\tvar templateFieldsCreate = `shift_worker=${api.state.active_worker.shiftWorker}^shift_position=${api.item.value._row_data.uniqueValue}`;\n\tvar templateFieldsUpdate = `shift_position=${api.item.value._row_data.uniqueValue}^order=0`;\n\tif (api.state.active_worker.position == 'unassigned') {\n\t\t//order = imports.EyvaUtils.getNextOrder('x_802331_eyva_shift_position_worker', `shift_position=${api.item.value._row_data.uniqueValue}`, 'shift_position', 'order');\n\t\tparams = {\n\t\t\toperation: 'create',\n\t\t\ttemplateFields: templateFieldsCreate\n\t\t};\n\t\tif (!api.state.auto_save) {\n\t\t\tparams.recordId = api.state.active_worker.shiftPositionWorker;\n\t\t\tparams.templateFieldsUpdate = templateFieldsUpdate;\n\t\t\tparams.shiftWorker = api.data.look_up_shift_workers.results.find(sw => sw._row_data.uniqueValue == api.state.active_worker.shiftWorker);\n\t\t\tparams.shiftPosition = api.data.look_up_shift_positions.results.find(sp => sp._row_data.uniqueValue == api.item.value._row_data.uniqueValue);\n\t\t\tparams.shiftPositionWorker = api.state.shift_position_workers_replica.find(spw => spw._row_data.uniqueValue == api.state.active_worker.shiftPositionWorker);\n\t\t}\n\t} else if (api.item.value.unassignedWorkers) {\n\t\tif (api.state.active_worker.position == 'unassigned') {\n\t\t\treturn {abortAction: true};\n\t\t}\n\t\tparams = {\n\t\t\toperation: 'delete',\n\t\t\trecordId: api.state.active_worker.shiftPositionWorker\n\t\t};\n\t\tif (!api.state.auto_save) {\n\t\t\tparams.shiftPosition = api.item.value,\n\t\t\tparams.shiftPositionWorker = api.state.shift_position_workers_replica.find(spw => spw._row_data.uniqueValue == api.state.active_worker.shiftPositionWorker);\n\t\t}\n\t} else {\n\t\t//order = imports.EyvaUtils.getNextOrder('x_802331_eyva_shift_position_worker', `shift_position=${api.item.value._row_data.uniqueValue}`, 'shift_position', 'order');\n\t\tparams = {\n\t\t\toperation: 'update',\n\t\t\trecordId: api.state.active_worker.shiftPositionWorker,\n\t\t\ttemplateFields: templateFieldsUpdate\n\t\t};\n\t\tif (!api.state.auto_save) {\n\t\t\tparams.templateFieldsCreate = templateFieldsCreate;\n\t\t\tparams.shiftPosition = api.data.look_up_shift_positions.results.find(sp => sp._row_data.uniqueValue == api.item.value._row_data.uniqueValue);\n\t\t\tparams.shiftPositionWorker = api.state.shift_position_workers_replica.find(spw => spw._row_data.uniqueValue == api.state.active_worker.shiftPositionWorker);\n\t\t}\n\t}\n\tparams.newPosition = api.item.value.position.value;\n\treturn params;\n}",
