                                                "clientScript": null,
                                                "conditional": null,
                                                "declarativeAction": null,
                                                "event": {
                                                    "apiName": "sn_uxf.MACROPONENT_STATE_UPDATE_REQUESTED",
                                                    "payload": {
                                                        "script": {
                                                            "apiVersion": "1.0.0",
                                                            "controllerElementId": null,
                                                            "inlineScript": "/**\n* @param {params} params\n* @param {api} params.api\n* @param {any} params.event\n*/\nfunction evaluateEvent({api, event}) {\n\tif (!api.state.worker_search_input) {\n\t\treturn;\n\t}\n    var shiftWorkersOnModal = api.state.msp_modal_data.shiftWorkers;\n\tvar workerSearchedOnModal = shiftWorkersOnModal.find(wkr => {\n\t\treturn wkr.label.toLowerCase() == api.state.worker_search_input.toLowerCase();\n\t});\n\tvar workerSearched = api.data.look_up_workers.results.find(wkr => {\n\t\treturn wkr._row_data.displayValue.toLowerCase() == api.state.worker_search_input.toLowerCase(); //Todo: Use worker id\n\t});\n\n\tif (workerSearchedOnModal) {\n\t\t// If find worker in modal's shift worker list, make active, move out of unassigned column, ensure not marked for deletion\n\t\tworkerSearchedOnModal.active = true;\n\t\tworkerSearchedOnModal.assigned = true;\n\t\tworkerSearchedOnModal.deleted = false;\n\t} else if (workerSearched) {\n\t\t// If find worker in complete worker list, add record\n\t\tshiftWorkersOnModal.push({\n\t\t\tid: workerSearched._row_data.uniqueValue,\n\t\t\tlabel: workerSearched._row_data.displayValue,\n\t\t\tadult: workerSearched.adult.value,\n\t\t\tactive: true,\n\t\t\tassigned: true\n\t\t});\n\t} else {\n\t\t// If can't find worker input, add artificial record\n\t\tshiftWorkersOnModal.push({\n\t\t\tid: 'new-worker',\n\t\t\tlabel: api.state.worker_search_input,\n\t\t\tadult: !api.state.kid_status_input,\n\t\t\tactive: true,\n\t\t\tassigned: true\n\t\t});\n\t}\n\treturn {\n\t\tpropName: 'msp_modal_data',\n\t\tvalue: JSON.parse(JSON.stringify(api.state.msp_modal_data)) //since object should be small, use a \"deep copy\" to trigger a \"change in client state\"\n\t};\n}",
                                                            "scriptSysId": null,
                                                            "target": null
                                                        },
                                                        "type": "CLIENT_TRANSFORM_SCRIPT"
                                                    },
                                                    "sysId": "32408b42ff7a10109046e490703bf176"
                                                },
                                                "operation": null,
                                                "targetId": "clkojesbggaaccngddohhvrpumlddlm",
                                                "type": "EVENT"
                                            }
                                        ]
                                    }
