                                                                                                        "script": {
                                                                                                            "apiVersion": "1.0.0",
                                                                                                            "controllerElementId": null,
                                                                                                            "inlineScript": "/**\n* @param {params} params\n* @param {api} params.api\n* @param {any} params.event\n*/\nfunction evaluateEvent({api, event}) {\n\tif (api.item.value.shiftWorker) {\n\t\t// If clicked worker on selected shift, mark for deletion\n\t\tapi.item.value.deleted = true;\n\t\tapi.item.value.active = false;\n\t\tapi.item.value.assigned = false;\n\t} else {\n\t\t// If worker not already on selected shift, filter out worker\n\t\tapi.state.msp_modal_data.shiftWorkers = api.state.msp_modal_data.shiftWorkers.filter(wkr => {\n\t\t\treturn wkr.label != api.item.value.label; //Todo: Use worker id, but would require new workers to have unique id, maybe current time (to the second)\n\t\t});\n\t}\n\treturn {\n\t\tpropName: 'msp_modal_data',\n\t\tvalue: JSON.parse(JSON.stringify(api.state.msp_modal_data)) //since object should be small, use a \"deep copy\" to trigger a \"change in client state\"\n\t};\n}",
                                                                                                            "scriptSysId": null,
                                                                                                            "target": null
                                                                                                        },
                                                                                                        "type": "CLIENT_TRANSFORM_SCRIPT"
